mapper.select:
select  
	from FIN_CASH_PLAN
	where FIN_CASH_PLAN.CASH_ID = (select CASH_ID from FIN_CASH_INFO
									where FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
									    and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
									    and FIN_CASH_INFO.FINPROD_ID = #{finprodId}
									    and FIN_CASH_INFO.FINPROD_TYPE = #{finprodType}

											and FIN_CASH_INFO.BRANCH = #{branch}
										)
	order by FIN_CASH_PLAN.MDATE ASC
